import React from "react";
import { AppBar, Grid, Typography } from "@material-ui/core";
import { useStyles } from "./StyleMaterialUI";

import EvStationIcon from "@material-ui/icons/EvStation";
import MenuIcon from "@material-ui/icons/Menu";

const Navbar = ({ toggleSidebar }) => {
  const classes = useStyles();
  return (
    <AppBar position="absolute" className={classes.navbar}>
      <Grid container>
        <Grid item xs={10} className={classes.alignLeft}>
          <Typography variant="h1" className={classes.navHeading}>
            C
            <EvStationIcon fontSize="inherit" className={classes.navIcon} />
            r-Chargers
          </Typography>
        </Grid>

        <Grid item xs={2} className={classes.alignRight}>
          <Typography variant="h1" className={classes.navHeading}>
            <MenuIcon
              fontSize="inherit"
              className={classes.navIcon}
              onClick={toggleSidebar}
            />
          </Typography>
        </Grid>
      </Grid>
    </AppBar>
  );
};

export default Navbar;
