import React from "react";
import {
  Link,
  Typography,
  Grid,
  Paper,
  DialogContentText,
} from "@material-ui/core";
import EmailIcon from "@material-ui/icons/Email";
import PhoneIcon from "@material-ui/icons/Phone";
import { useStyles } from "./StyleMaterialUI";

const DialogMainInfo = ({ activeData }) => {
  const classes = useStyles();

  return (
    <div>
      <Grid container spacing={2}>
        <Grid item xs={12} md={6}>
          <Paper className={classes.dialogContact} elevation={5}>
            {activeData.AddressInfo ? (
              <>
                <div className={classes.centerText}>
                  {activeData.AddressInfo.Town
                    ? activeData.AddressInfo.Town
                    : ""}
                </div>
                <div className={classes.centerText}>
                  {activeData.AddressInfo.AddressLine2
                    ? activeData.AddressInfo.AddressLine2
                    : ""}
                </div>
                <div className={classes.centerText}>
                  {activeData.AddressInfo.AddressLine1
                    ? activeData.AddressInfo.AddressLine1
                    : ""}
                </div>
                <div className={classes.centerText}>
                  {activeData.AddressInfo.Postcode
                    ? activeData.AddressInfo.Postcode
                    : ""}
                </div>
              </>
            ) : (
              "No Adress Info"
            )}
          </Paper>
        </Grid>
        <Grid item xs={12} md={6}>
          <Paper className={classes.dialogContact} elevation={5}>
            {activeData.AddressInfo ? (
              <>
                {activeData.AddressInfo.ContactTelephone1 ? (
                  <div className={classes.centerText}>
                    <PhoneIcon fontSize="small" />{" "}
                    {activeData.AddressInfo.ContactTelephone1}
                  </div>
                ) : (
                  ""
                )}
                {activeData.AddressInfo.ContactTelephone2 ? (
                  <div className={classes.centerText}>
                    <PhoneIcon fontSize="small" />{" "}
                    {activeData.AddressInfo.ContactTelephone2}
                  </div>
                ) : (
                  ""
                )}
                {activeData.AddressInfo.ContactEmail ? (
                  <div className={classes.centerText}>
                    <Link
                      href={`mailto:${activeData.AddressInfo.ContactEmail}`}
                    >
                      <EmailIcon fontSize="small" />
                      Send E-mail
                    </Link>{" "}
                  </div>
                ) : (
                  ""
                )}
                {activeData.AddressInfo.RelatedURL ? (
                  <div className={classes.centerText}>
                    <Link
                      className={classes.bold}
                      target="_blank"
                      rel="noopener"
                      href={activeData.AddressInfo.RelatedURL}
                    >
                      Related Link
                    </Link>{" "}
                  </div>
                ) : (
                  ""
                )}
              </>
            ) : (
              "No Contact info"
            )}
            {activeData.DataProvider && activeData.DataProvider.WebsiteURL ? (
              <div className={classes.centerText}>
                <Link
                  className={classes.bold}
                  target="_blank"
                  rel="noopener"
                  href={activeData.DataProvider.WebsiteURL}
                >
                  Provider Link
                </Link>{" "}
              </div>
            ) : (
              ""
            )}
          </Paper>
        </Grid>
        <Grid item xs={12}>
          <Paper elevation={5} className={classes.dialogBasicInfo}>
            <Typography
              style={{ marginBottom: "0.4rem" }}
              variant="h6"
              className={classes.boldGray}
            >
              BASIC INFO
            </Typography>
            <DialogContentText>
              <span className={classes.boldGray}>Access Comment: </span>{" "}
              {activeData.AddressInfo.AccessComments
                ? activeData.AddressInfo.AccessComments
                : "unknown / no data"}
            </DialogContentText>
            <DialogContentText>
              <span className={classes.boldGray}>General Comment: </span>{" "}
              {activeData.GeneralComments
                ? activeData.GeneralComments
                : "unknown / no data"}
            </DialogContentText>
            <DialogContentText>
              <span className={classes.boldGray}>Usage Cost: </span>{" "}
              {activeData.UsageCost
                ? activeData.UsageCost
                : "unknown / no data"}
            </DialogContentText>
          </Paper>
        </Grid>

        {/* IF THERE INFO ABOUT CONNECTIONS */}
        {activeData.Connections
          ? activeData.Connections.map((conn, index) => (
              <Grid item xs={12} md={6} key={conn.ID}>
                <Paper className={classes.dialogConnects} elevation={5}>
                  <Typography variant="h6" className={classes.boldGray}>
                    Connection {index + 1}
                  </Typography>
                  <div className={classes.gray}>
                    <span className={classes.boldGray}>Amps:</span>
                    {conn.Amps ? conn.Amps : "unknown"}
                  </div>
                  <div className={classes.gray}>
                    <span className={classes.boldGray}>Voltage: </span>
                    {conn.Voltage ? conn.Voltage : "unknown"}
                  </div>
                  <div className={classes.gray}>
                    <span className={classes.boldGray}>Power KW: </span>
                    {conn.PowerKW ? conn.PowerKW : "unknown"}
                  </div>
                  <div className={classes.gray}>
                    <span className={classes.boldGray}>
                      Fast Charge Status:{" "}
                    </span>
                    {conn.Level && conn.Level.IsFastChargeCapable === false
                      ? "no"
                      : conn.Level && conn.Level.IsFastChargeCapable === true
                      ? "yes"
                      : "unknown"}
                  </div>
                  <div className={classes.gray}>
                    <span className={classes.boldGray}>Status Type: </span>
                    {conn.StatusType && conn.StatusType.Title !== "Unknown"
                      ? conn.StatusType.Title
                      : "unknown"}
                  </div>
                  <div className={classes.gray}>
                    <span className={classes.boldGray}>Quantity: </span>
                    {conn.Quantity ? conn.Quantity : "unknown"}
                  </div>
                </Paper>
              </Grid>
            ))
          : ""}
      </Grid>
    </div>
  );
};

export default DialogMainInfo;
