import React, { useState, useEffect } from "react";
import { MapContainer, TileLayer, Marker, LayersControl } from "react-leaflet";
import { Icon } from "leaflet";
import axios from "axios";
import chargerIcon from "leaflet/dist/images/charger.svg";

import { mapOption, basemaps } from "./components/mapOption";
import MapDialog from "./components/MapDialog";
import Navbar from "./components/Navbar";
import Sidebar from "./components/Sidebar";
import "./index.css";

// Material-UI
import { Typography, CircularProgress } from "@material-ui/core";
import { MuiThemeProvider, createMuiTheme } from "@material-ui/core/styles";
import { green, yellow } from "@material-ui/core/colors";

import { useStyles } from "./components/StyleMaterialUI";
import "leaflet/dist/leaflet.css";

const theme = createMuiTheme({
  palette: {
    primary: {
      main: green[900],
    },
    secondary: {
      main: yellow[600],
    },
  },
});

function App() {
  // ****************** STYLE ************************

  const classes = useStyles();

  // ****************** STATES ************************

  // ALL CHARGERS - To store the initial value - also for reset filtered chargers
  const [chargers, setChargers] = useState([]);
  const [filteredChargers, setFilteredChargers] = useState([]);
  const [activeData, setActiveData] = useState();
  const [isOpenDialog, setDialog] = useState(false);
  const [isOpenPhoto, setPhoto] = useState(false);
  const [loading, setLoading] = useState(false);
  const [isOpenSidebar, setSidebar] = useState(false);
  const [innerWidth, setInnerWidth] = useState(window.innerWidth);
  const [isError, setIsError] = useState(false);

  // For Handle Shown  info in selected option
  const [selectedActiveConn, setSelectedActiveConn] = useState(5);
  const [selectedActivePhoto, setSelectedActivePhoto] = useState(3);

  // *************** EFFECTS ************************

  // ******* Effect for Inner Width ************-
  useEffect(() => {
    setInnerWidth(window.innerWidth);
    console.log(`Width of the device is ${innerWidth}`);
    if (innerWidth > 600) setSidebar(true);
  }, [innerWidth]);

  // Call OpenCharge API Once => []
  useEffect(() => {
    axios
      .get(
        `https://api.openchargemap.io/v3/poi/?output=json&countrycode=CZ&longitude=16.6163633&latitude=49.1974147&distance=20&maxresults=80?key=1319a96c-8d88-4078-abb1-13277a893879`
      )
      .then((res) => {
        // load all chargers
        console.log(res.data);
        setFilteredChargers(res.data);
        setChargers(res.data);
        setLoading(false);
      })
      .catch((err) => {
        // resolve error
        console.log(err);
        setIsError(true);
      });
    setLoading(true);
  }, []);

  // ****************** Functions ************************

  const handleSelectedActiveConn = (event) => {
    setSelectedActiveConn(event);
  };
  const handleSelectedActivePhoto = (event) => {
    setSelectedActivePhoto(event);
  };

  const toggleDialog = () => {
    setDialog((prev) => !prev);
    if (isOpenPhoto) {
      setPhoto((prev) => !prev);
    }
  };

  const togglePhoto = () => {
    setPhoto((prev) => !prev);
    if (isOpenPhoto) {
      setPhoto(false);
    }
  };

  const toggleSidebar = () => setSidebar((prev) => !prev);

  // Function For Show current Data in Dialog - Handle clicked Data
  const updateActiveData = (data, id) => {
    data.filter((item) => (item.ID === id ? setActiveData(item) : []));
    toggleDialog();
  };

  // Filter Data By Number Of Connections
  const filterDataByConn = (data, para) => {
    let result;
    if (para < 4) {
      result = data.filter((item) => para === item.Connections.length);
    } else if (para === 4) {
      // this value means four and more
      result = data.filter((item) => item.Connections.length >= 4);
    } else {
      // For show all data
      result = data;
    }
    setFilteredChargers(result);

    // Show on select option current and reset second filtration
    handleSelectedActiveConn(para);
    handleSelectedActivePhoto(3);
  };

  // Filter Data By Photo Exist Or Not
  const filterDataByPhoto = (data, para) => {
    switch (para) {
      case 1:
        setFilteredChargers(data.filter((item) => item.MediaItems !== null));
        break;
      case 2:
        setFilteredChargers(data.filter((item) => item.MediaItems === null));
        break;
      default:
        setFilteredChargers(data);
        break;
    }

    // Show on select option current and reset second filtration
    handleSelectedActivePhoto(para);
    handleSelectedActiveConn(5);
  };

  return (
    <>
      <MuiThemeProvider theme={theme}>
        {loading ? (
          <CircularProgress
            className={classes.loading}
            thickness={6}
            size={50}
            color="primary"
          />
        ) : (
          ""
        )}
        {isError ? (
          <div className={classes.error}>
            <Typography variant="h4" className={classes.errorText}>
              There Is a Data Fetching Error!! Data currently working onlwith
              actual api key.
            </Typography>
          </div>
        ) : (
          ""
        )}

        <Navbar toggleSidebar={toggleSidebar} />
        <Sidebar
          innerWidth={innerWidth}
          toggleSidebar={toggleSidebar}
          isOpenSidebar={isOpenSidebar}
          filterDataByConn={filterDataByConn}
          chargers={chargers}
          filterDataByPhoto={filterDataByPhoto}
          selectedActiveConn={selectedActiveConn}
          selectedActivePhoto={selectedActivePhoto}
          filteredChargers={filteredChargers}
        />
        <MapContainer
          className={classes.mapContainer}
          center={mapOption.center}
          zoom={mapOption.zoom}
        >
          <TileLayer url={basemaps[0].url} />

          {/* https://www.youtube.com/watch?v=HsIQO25CknQ&ab_channel=%D0%9E%D1%81%D0%BD%D0%BE%D0%B2%D1%8B%D0%BF%D1%80%D0%BE%D0%B3%D1%80%D0%B0%D0%BC%D0%BC%D0%B8%D1%80%D0%BE%D0%B2%D0%B0%D0%BD%D0%B8%D1%8F%D0%B4%D0%BB%D1%8F%D0%B3%D0%B5%D0%BE%D0%B3%D1%80%D0%B0%D1%84%D0%BE%D0%B2 */}

          {filteredChargers.map((charger) => (
            <Marker
              key={charger.ID}
              position={[
                charger.AddressInfo.Latitude,
                charger.AddressInfo.Longitude,
              ]}
              icon={new Icon({ iconUrl: chargerIcon, iconSize: [40, 40] })}
              eventHandlers={{
                click: () => updateActiveData(filteredChargers, charger.ID),
              }}
            ></Marker>
          ))}
        </MapContainer>

        <Typography style={{ fontFamily: "Roboto" }}>
          <MapDialog
            activeData={activeData}
            toggleDialog={toggleDialog}
            isOpenDialog={isOpenDialog}
            togglePhoto={togglePhoto}
            isOpenPhoto={isOpenPhoto}
          />
        </Typography>
      </MuiThemeProvider>
    </>
  );
}

export default App;
