import React from "react";
import chargerImg from "../img/charger-pic.jpg";
import { useStyles } from "./StyleMaterialUI";
import {
  Input,
  Drawer,
  Typography,
  Box,
  Button,
  Link,
  Select,
  MenuItem,
} from "@material-ui/core";

import KeyboardArrowDownIcon from "@material-ui/icons/KeyboardArrowDown";
const Sidebar = ({
  isOpenSidebar,
  innerWidth,
  toggleSidebar,
  filterDataByConn,
  chargers,
  filterDataByPhoto,
  selectedActivePhoto,
  selectedActiveConn,
}) => {
  const classes = useStyles();

  return (
    <>
      <Drawer
        variant="persistent"
        anchor={innerWidth > 600 ? "right" : "bottom"}
        open={isOpenSidebar}
        transitionDuration={500}
      >
        {/************************* HANDLE MOBILE DEVICES ********************-*/}
        <Box className={classes.sideBarContainer}>
          {innerWidth > 600 ? null : (
            <Box className={classes.alignCenter}>
              <Button
                variant="contained"
                onClick={toggleSidebar}
                color="secondary"
                startIcon={<KeyboardArrowDownIcon fontSize="large" />}
                size="large"
                className={classes.sideBarCloseButton}
              >
                Close Sidebar
              </Button>
            </Box>
          )}

          {/************************* ABOUT APP ********************-*/}
          <Box>
            <Typography
              variant="h5"
              className={classes.sidebarHeader}
              style={{ marginTop: "4rem" }}
            >
              About App
            </Typography>
            <Typography variant="body1" className={classes.sidebarAbout}>
              This App shows Car-Charger Stations in Brno. App is only for
              studying purposes. I tried to work with external JSON data and
              visualize them in the map. This is my first project in React.JS
              and there could be some things that could be done better. This App
              is responsive for mobile devices. Currently using{" "}
              <Link
                href="https://openchargemap.org/site/develop/api"
                className={classes.attrLink}
              >
                OpenCharge Api
              </Link>
              {" &"}{" "}
              <Link href="https://leafletjs.com/" className={classes.attrLink}>
                Leaflet.JS.
              </Link>
              {" &"}{" "}
              <Link
                href="https://leaflet-extras.github.io/leaflet-providers/preview/"
                className={classes.attrLink}
              >
                Leaflet providers.
              </Link>
            </Typography>
          </Box>

          {/************************* FILTER ********************-*/}

          <Box>
            <Typography variant="h5" className={classes.sidebarHeader}>
              Filter
            </Typography>
            <Typography variant="h6" className={classes.sidebarSubHeader}>
              By number of connections
            </Typography>
            <Box className={classes.alignCenter}>
              <Select
                input={<Input />}
                fullWidth={true}
                variant="outlined"
                color="primary"
                className={classes.sidFilterInput}
                value={selectedActiveConn}
                onChange={(e) => filterDataByConn(chargers, e.target.value)}
              >
                <MenuItem value={1}>one</MenuItem>
                <MenuItem value={2}>two</MenuItem>
                <MenuItem value={3}>three</MenuItem>
                <MenuItem value={4}>four or more</MenuItem>
                <MenuItem value={5}>all</MenuItem>
              </Select>
            </Box>

            <Typography variant="h6" className={classes.sidebarSubHeader}>
              By Photos
            </Typography>
            <Box className={classes.alignCenter}>
              <Select
                input={<Input name="numOfConnections" id="numOfConnections" />}
                fullWidth={true}
                name="filter"
                variant="filled"
                color="primary"
                className={classes.sidFilterInput}
                value={selectedActivePhoto}
                onChange={(e) => filterDataByPhoto(chargers, e.target.value)}
              >
                <MenuItem value={1}> with photos</MenuItem>
                <MenuItem value={2}>without photos</MenuItem>
                <MenuItem value={3}>all</MenuItem>
              </Select>
            </Box>
          </Box>
          <Box className={classes.alignCenter}>
            <img
              src={chargerImg}
              alt="Charger"
              className={classes.imgCharger}
            ></img>
          </Box>
        </Box>
      </Drawer>
    </>
  );
};

export default Sidebar;
